    /**
     * Tests getting all Obligations.
     *
     * @return    Collection
     */
    public List<Obligation> testGetAll() throws Throwable {
    LOGGER.info( "ObligationTest:testGetAll() - Retrieving Collection of Obligations:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Obligation : " );
    List<Obligation> collection  = null;

    try {
        // call the static get method on the ObligationService
        collection = service.getAllObligation();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Obligation currEntity  = null;
            Iterator<Obligation> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getObligationId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

